<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#222}h1{font-size:20px;margin-bottom:4px}.muted{color:#666}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #bbb;padding:7px}th{background:#f0f0f0;text-align:left}.right{text-align:right}.total{font-weight:bold;font-size:13px}</style></head><body><h1>QUOTATION</h1><div class="muted"><?= esc($quotation['quotation_no']) ?> | <?= esc($quotation['created_at'] ?? date('Y-m-d')) ?></div><hr><strong><?= esc($quotation['company_name']) ?></strong><br><?= nl2br(esc($quotation['company_address'] ?? '')) ?><p><strong>Untuk:</strong> <?= esc($quotation['customer_name'] ?? '-') ?><br><?= nl2br(esc($quotation['customer_address'] ?? '')) ?><br><?= esc($quotation['customer_phone'] ?? '') ?></p><h2><?= esc($quotation['title']) ?></h2><table><thead><tr><th>Produk</th><th>Qty</th><th>Harga Satuan</th><th>Diskon</th><th class="right">Total</th></tr></thead><tbody><?php foreach ($quotation['items'] as $item): ?><tr><td><?= esc($item['product_name']) ?><br><?= esc($item['description'] ?? '') ?></td><td><?= esc($item['quantity']) ?> <?= esc($item['unit']) ?></td><td>Rp <?= number_format((float)$item['unit_price'], 0, ',', '.') ?></td><td><?= esc($item['discount_percent']) ?>%</td><td class="right">Rp <?= number_format((float)$item['line_total'], 0, ',', '.') ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="4" class="right">Subtotal</th><th class="right">Rp <?= number_format((float)$quotation['subtotal'], 0, ',', '.') ?></th></tr><tr><th colspan="4" class="right">Pajak</th><th class="right">Rp <?= number_format((float)$quotation['tax_amount'], 0, ',', '.') ?></th></tr><tr class="total"><th colspan="4" class="right">GRAND TOTAL</th><th class="right">Rp <?= number_format((float)$quotation['grand_total'], 0, ',', '.') ?></th></tr></tfoot></table><p><?= nl2br(esc($quotation['notes'] ?? '')) ?></p></body></html>
